import{_ as i,o as a,c as t,a2 as h}from"./chunks/framework.yo2CxoV2.js";const n="/ordloom-docs/assets/crm-overview.DJOCzxh2.png",F=JSON.parse('{"title":"CRM 客户关系子应用","description":"","frontmatter":{},"headers":[],"relativePath":"guides/crm.md","filePath":"guides/crm.md","lastUpdated":1794716518000}'),p={name:"guides/crm.md"};function l(e,s,d,k,o,r){return a(),t("div",null,[...s[0]||(s[0]=[h('<h1 id="crm-客户关系子应用" tabindex="-1">CRM 客户关系子应用 <a class="header-anchor" href="#crm-客户关系子应用" aria-label="Permalink to &quot;CRM 客户关系子应用&quot;">​</a></h1><p><code>ordloom-crm</code> 0.1.0 是内部员工使用的客户关系 MVP，要求 Python 3.9+、Django 4.2+ 与 <code>ordloom&gt;=1.1.0,&lt;2</code>，不依赖会员、商城或其他业务子应用。Ordloom 1.2.1 的应用目录包含其接入信息。</p><p>隔离示例中的客户概览（合成业务数据）：</p><p><img src="'+n+`" alt="CRM 客户概览"></p><h2 id="安装与权限" tabindex="-1">安装与权限 <a class="header-anchor" href="#安装与权限" aria-label="Permalink to &quot;安装与权限&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ordloom==</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.2.1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ordloom-crm==</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.1.0</span></span></code></pre></div><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">INSTALLED_APPS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;ordloom_crm.apps.ExtensionConfig&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> manage.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> manage.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> collectstatic</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --noinput</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> manage.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span></code></pre></div><p>CRM 没有公开 URL，不需要额外 include。为有效员工授予所需模型的 <code>view/add/change/delete</code> 权限，菜单出现「客户关系 → 客户关系概览」；概览和任务同时要求 <code>ordloom_crm.view_customer</code>、<code>ordloom_crm.view_lead</code>。客户、联系人、线索和跟进记录继续通过 Ordloom 模型管理界面编辑，不引入另一套业务写入 API。</p><table tabindex="0"><thead><tr><th>模型</th><th>首版能力</th><th>权限范围</th></tr></thead><tbody><tr><td>客户 <code>customer</code></td><td>名称、潜在/合作中/停用状态、行业、来源、负责人、备注</td><td>普通员工只管理自己负责的客户，创建时负责人为本人；超级管理员可分配和转交给有效员工</td></tr><tr><td>联系人 <code>contact</code></td><td>客户、姓名、职位、邮箱、电话、备注</td><td>随客户负责人隔离；关联选择与提交校验拒绝其他负责人的客户</td></tr><tr><td>线索 <code>lead</code></td><td>客户、名称、来源、阶段、预计金额、下次跟进时间、流失原因</td><td>随客户负责人隔离，不能通过伪造关联跨范围写入</td></tr><tr><td>跟进 <code>followup</code></td><td>客户、可选线索、电话/会面/邮件/备注、内容、记录人、时间</td><td>服务端记录当前员工，只追加；后台与核心 API 不提供修改或删除</td></tr></tbody></table><p>客户转交会同步改变其联系人、线索和跟进记录的可见范围，历史记录人保留。跟进关联的线索必须属于同一客户；已有跟进的线索不能移到另一个客户。带线索或跟进的客户受外键保护，需保留业务记录。联系邮箱和电话仅供业务登记，不表示经过身份验证。</p><h2 id="线索和跟进流程" tabindex="-1">线索和跟进流程 <a class="header-anchor" href="#线索和跟进流程" aria-label="Permalink to &quot;线索和跟进流程&quot;">​</a></h2><ol><li>创建客户并记录联系人，再为该客户建立线索；线索从「新线索」开始。</li><li>按「新线索 → 已联系 → 已确认意向 → 已成交」推进；任一进行中阶段可转为「已流失」，必须填写流失原因。</li><li>禁止跳过阶段或重新打开已成交/已流失线索。结束时自动清除下次跟进时间。</li><li>在跟进记录中选择客户和可选线索，记录本次沟通；需要再次提醒时，在对应线索设置新的下次跟进时间。新增跟进记录不会自动更改线索阶段或时间。</li></ol><p>预计金额使用两位小数 Decimal 与非负数据库约束，以 CNY 元计；概览按精确小数汇总，并以字符串传输，不代表已收款或会计收入。概览只展示当前权限范围内的客户数、阶段分布、进行中预计金额及最多 20 条待办线索，不返回联系人电话、邮箱或完整跟进内容。宿主隐藏概览依赖字段时，读取会拒绝，不回退为绕过字段权限的查询。</p><h2 id="到期跟进提醒" tabindex="-1">到期跟进提醒 <a class="header-anchor" href="#到期跟进提醒" aria-label="Permalink to &quot;到期跟进提醒&quot;">​</a></h2><p>宿主 cron 或任务平台显式调度：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 默认预览，不生成消息</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> manage.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ordloom_run_app_task</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ext:crm.followups</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --user</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">员工主</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">键</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 显式执行</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> manage.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ordloom_run_app_task</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ext:crm.followups</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --user</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">员工主</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">键</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --apply</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span></span></code></pre></div><p>任务账号必须拥有客户和线索查看权限，扫描仅覆盖其当前可见范围。扫描进行中且已到下次跟进时间的线索，跳过停用客户，并向当前有效员工负责人发送站内提醒；普通员工不能替其他负责人扫描，超级管理员可调度全范围。任务复用 SDK 共享缓存租约与通知去重，按线索主键和跟进时间生成去重键，重跑不会重复通知；设置新的到期时间后可再次提醒。客户转交、停用、线索关闭或权限撤销后按当前状态重读。</p><p>单模型扫描最多 1000 条对象，超预算明确失败，不静默截断。多实例部署使用同一原子共享缓存。通知复用站内通知中心，不外发邮件、短信或微信；调度由宿主负责，首版不提供网页执行按钮。</p><h2 id="搭建组件与停用" tabindex="-1">搭建组件与停用 <a class="header-anchor" href="#搭建组件与停用" aria-label="Permalink to &quot;搭建组件与停用&quot;">​</a></h2><p>大屏/H5 编辑器的「子应用」分类提供「客户关系入口」静态卡片，只有标题和说明，不绑定客户业务数据、不向公开页面提供 CRM 读取能力。</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">ORDLOOM_DISABLED_APPS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;crm&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p>停用后菜单、专用页、组件和任务关闭，模型写入也拒绝；保留业务表和历史数据。</p><h2 id="验证与边界" tabindex="-1">验证与边界 <a class="header-anchor" href="#验证与边界" aria-label="Permalink to &quot;验证与边界&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/test_products.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --crm-only</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/test_products.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --wechat</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/test_products.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --wechat</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --email-user</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/test_ownership_postgres.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --crm</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/test_products_install.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --crm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/crm-install.json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/test_products_install.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --operations</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/nine-apps-install.json</span></span></code></pre></div><p>回归覆盖对象隔离、伪造负责人/关联、客户转交、阶段与金额校验、只追加跟进、字段权限、停用、任务预览/租约/去重/重排时间，以及默认和邮箱/UUID User。安装验收使用实际 wheel/sdist，检查独立安装、九应用组合、迁移无漂移、静态资源及任务。</p><p>首版没有客户公海池、团队共享/销售组织、自动分配、商机报价、合同与收款、导入去重、会员自动转客户或邮件群发；已有工作区权限不自动成为 CRM 团队授权。后续独立子应用顺序为预约、审批；会员身份恢复、CMS 历史恢复、支付和微信业务消息继续按主路线图推进。</p><h2 id="公海池与团队共享" tabindex="-1">公海池与团队共享 <a class="header-anchor" href="#公海池与团队共享" aria-label="Permalink to &quot;公海池与团队共享&quot;">​</a></h2><ul><li><strong>公海池</strong>：负责人可将自己的客户释放到公海（附原因，<code>release_to_pool</code>，需为当前负责人）；存在未关闭线索的客户不能释放。公海客户对所有具备 CRM 权限的员工可见（后台「公海客户」列表或 SDK 概览），任何员工可领取（<code>claim_from_pool</code>，行锁防并发抢领，单负责人名下上限 200）。公海期间客户的联系人/线索/跟进冻结隐藏（超级管理员除外），领取后按新负责人隔离恢复。释放会清空团队共享配置。</li><li><strong>团队共享</strong>：负责人可给其他员工授予客户级 read/edit 协作者（<code>CustomerCollaborator</code>，客户+用户唯一）。read 协作者仅可见；edit 协作者可编辑客户联系信息、添加跟进（作者留痕）、推进线索，但删除仍限负责人，且不可变更负责人/状态/公海字段。释放到公海即解除全部共享。</li><li>公海超时检查任务 <code>ext:crm.pool_scan</code> 统计超过 <code>ORDLOOM_CRM[&quot;pool_days&quot;]</code>（默认 30 天，1–365）未领取的公海客户数量。</li></ul>`,29)])])}const g=i(p,[["render",l]]);export{F as __pageData,g as default};
